# the fixed clock makes every commit hash and date repeatable; learners' own hashes and dates will differ
GIT_PRE = [
    'export GIT_PAGER=cat GIT_AUTHOR_NAME="Ada Learner" GIT_AUTHOR_EMAIL="ada@example.com" GIT_COMMITTER_NAME="Ada Learner" GIT_COMMITTER_EMAIL="ada@example.com"',
    "CLOCK=1768471200",
    'git() { CLOCK=$((CLOCK+3600)); GIT_AUTHOR_DATE="@$CLOCK +0000" GIT_COMMITTER_DATE="@$CLOCK +0000" command git "$@"; }',
    'mkdir -p "$HOME/gitwork"',
]

